files.content:
:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #00cec9;
  --text: #f5f6fa;
  --muted: #a0a0b8;
  --radius: 16px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.subtitle {
  color: var(--muted);
  font-size: 0.95rem;
}

.card {
  width: 100%;
  aspect-ratio: 4 / 3;
  perspective: 1000px;
  cursor: pointer;
  border-radius: var(--radius);
  outline: none;
}

.card:focus-visible {
  box-shadow: 0 0 0 3px var(--accent);
}

.card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.45s ease;
  transform-style: preserve-3d;
}

.card.flipped .card-inner {
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  box-shadow: var(--shadow);
}

.card-front {
  background: var(--surface);
  border: 2px solid var(--primary);
}

.card-back {
  background: var(--primary);
  transform: rotateY(180deg);
}

.card-text {
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  word-break: break-word;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 14px 16px;
  border: 2px solid var(--primary);
  border-radius: 12px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
}

.btn:hover {
  background: rgba(108, 92, 231, 0.2);
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: rgba(108, 92, 231, 0.35);
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
}

.btn-primary:hover {
  background: #7d6ff0;
  border-color: var(--accent);
}

.btn-primary:active {
  background: #5a4bd4;
}

.status {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
}

.status .btn-primary {
  flex: 0 0 auto;
  padding: 14px 24px;
}

.known-count {
  font-size: 1rem;
  color: var(--muted);
  font-weight: 600;
}

@media (max-width: 400px) {
  .title { font-size: 1.5rem; }
  .card-text { font-size: 1.25rem; }
  .status { flex-direction: column; align-items: stretch; }
  .status .btn-primary { width: 100%; }
  .known-count { text-align: center; }
}

const cards = [
  { word: 'Ephemeral', meaning: 'Lasting for a very short time' },
  { word: 'Serendipity', meaning: 'A fortunate accidental discovery' },
  { word: 'Resilient', meaning: 'Able to recover quickly from difficulty' },
  { word: 'Luminous', meaning: 'Giving off light; bright' },
  { word: 'Meticulous', meaning: 'Showing great attention to detail' }
];

let currentIndex = 0;
let flipped = false;
const known = new Set();

const cardEl = document.getElementById('card');
const wordEl = document.getElementById('word');
const meaningEl = document.getElementById('meaning');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');
const gotItBtn = document.getElementById('gotItBtn');
const knownCountEl = document.getElementById('knownCount');

function render() {
  const card = cards[currentIndex];
  wordEl.textContent = card.word;
  meaningEl.textContent = card.meaning;
  cardEl.classList.toggle('flipped', flipped);
  cardEl.setAttribute('aria-label', flipped ? `Meaning: ${card.meaning}. Press Enter or Space to flip.` : `Word: ${card.word}. Press Enter or Space to flip.`);
  knownCountEl.textContent = `Known: ${known.size} / ${cards.length}`;
  prevBtn.disabled = currentIndex === 0;
  nextBtn.disabled = currentIndex === cards.length - 1;
  gotItBtn.disabled = known.has(currentIndex);
  gotItBtn.textContent = known.has(currentIndex) ? 'Known ✓' : 'Got it';
}

function flip() {
  flipped = !flipped;
  render();
}

function goPrev() {
  if (currentIndex > 0) {
    currentIndex--;
    flipped = false;
    render();
  }
}

function goNext() {
  if (currentIndex < cards.length - 1) {
    currentIndex++;
    flipped = false;
    render();
  }
}

function markKnown() {
  if (!known.has(currentIndex)) {
    known.add(currentIndex);
    render();
  }
}

cardEl.addEventListener('click', flip);
cardEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    flip();
  }
});

prevBtn.addEventListener('click', goPrev);
nextBtn.addEventListener('click', goNext);
gotItBtn.addEventListener('click', markKnown);

render();
